    const seam=(points,width)=>{c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));for(const[color,w,dy]of[['#382a19',width*1.3,0],['#886833',width,0],['#c4a966',width*.5,-width*.13],['#e5ca83',width*.12,-width*.21]]){c.save();c.translate(-width*.09,dy);c.strokeStyle=color;c.lineWidth=w;c.stroke();c.restore();}};
    seam([[.025,.08],[.025,.94],[.97,.94],[.97,.08]],.045);seam([[0,.49],[1,.49]],.042);seam([[.5,.05],[.5,.49]],.035);seam([[.25,.49],[.25,.95]],.035);seam([[.75,.49],[.75,.95]],.035);
