    for(let k=0;k<3;k++)softStrand(p,'hair'+k,x+drawW*(.83+k*.035),y+drawH*(.29+k*.05),drawH*(.10+k*.012),.014,'red',6,{angle:.28+k*.18,impulse:celebrating?.006:0});
